usage.rust:
use crate::parts::file_hash::{hash_bytes, hash_file, Algorithm, Hasher};

// A file, streamed in 64 KiB blocks (memory use stays constant)
let digest = hash_file(Algorithm::Blake3, "model.safetensors")?;
println!("{digest}"); // lowercase hex, same as Python's hexdigest()

// Bytes in memory: same as hashlib.sha256(b"abc").hexdigest()
let abc = hash_bytes(Algorithm::Sha256, b"abc");
assert_eq!(abc.to_hex(), "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad");

// Pieces arriving one at a time: how the input is split never changes the digest
let mut hasher = Hasher::new(Algorithm::Sha256);
hasher.update(b"a").update(b"bc");
assert_eq!(hasher.finalize(), abc);
